package in.pocketwise.widget;
import android.appwidget.AppWidgetManager; import android.appwidget.AppWidgetProvider; import android.content.Context; import android.content.Intent; import android.widget.RemoteViews; import android.net.Uri;
public class PocketWiseWidgetProvider extends AppWidgetProvider { @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);} static void update(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_pocketwise);var p=c.getSharedPreferences("pw_widget",0);v.setTextViewText(R.id.widget_balance,p.getString("balance","Open PocketWise to sync"));v.setTextViewText(R.id.widget_week,p.getString("week","7-day spending · —"));Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("https://nithannajeeb8-alt.github.io/PocketWise/?quickadd=expense"));v.setOnClickPendingIntent(R.id.widget_add,android.app.PendingIntent.getActivity(c,id,i,android.app.PendingIntent.FLAG_UPDATE_CURRENT|android.app.PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);} static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(int id:m.getAppWidgetIds(new ComponentName(c,PocketWiseWidgetProvider.class)))update(c,m,id);} }